// bindings/python/tests/fixtures/services_tools.ts
//
// Exports the @ryuhq/services tool registry (packages/services/src/tools) for
// the Python port in bindings/python/ryu_sdk/services/tools:
//
//   - `manifest` (the default): every tool's name, service, title,
//     description, annotations, default approval, input JSON Schema and
//     output JSON Schema (the MCP outputSchema, `{ data, meta }`), in
//     registry order, plus the selection prefixes and the constants the
//     Python tool bodies share. Committed as
//     bindings/python/ryu_sdk/services/tools/manifest.json and loaded at
//     runtime, so the Python tools cannot drift from the TypeScript ones.
//   - `vectors`: argument cases run through each tool's zod schema (accepted
//     with the parsed value, or rejected with the issue paths and codes), for
//     the Python argument validator to reproduce. Committed as
//     bindings/python/tests/fixtures/services_tools_vectors.json.
//   - `output-cases`: the stubbed replies every tool runs against in the
//     outputSchema conformance tests (packages/services/test/tool-output-cases.ts:
//     one success case per tool plus result variants), for
//     test_services_tools_output.py to run every Python body against. Committed
//     as bindings/python/tests/fixtures/services_tools_output_cases.json.
//
// Regenerate (test_services_tools_registry.py re-runs both when bun is
// installed and fails if a committed file is stale):
//
//   bun bindings/python/tests/fixtures/services_tools.ts manifest > bindings/python/ryu_sdk/services/tools/manifest.json
//   bun bindings/python/tests/fixtures/services_tools.ts vectors > bindings/python/tests/fixtures/services_tools_vectors.json
//   bun bindings/python/tests/fixtures/services_tools.ts output-cases > bindings/python/tests/fixtures/services_tools_output_cases.json

