function vectors() {
	const covered = new Set(CASES.map(([name]) => name));
	const uncovered = RYU_TOOLS.map((tool) => tool.name).filter(
		(name) => !covered.has(name)
	);
	if (uncovered.length > 0) {
		throw new Error(`No argument vectors for: ${uncovered.join(", ")}`);
	}
	return {
		description:
			"Tool arguments run through each @ryuhq/services tool's zod schema. Generated by bindings/python/tests/fixtures/services_tools.ts; do not edit.",
		cases: CASES.map(([name, input]) => {
			const tool = getRyuTool(name);
			if (tool === undefined) {
				throw new Error(`Unknown tool ${name}`);
			}
			const parsed = tool.inputSchema.safeParse(input);
			return parsed.success
				? { tool: name, input, ok: true, value: parsed.data }
				: {
						tool: name,
						input,
						ok: false,
						issues: parsed.error.issues.map((issue) => ({
							code: issue.code,
							path: issue.path.map(String).join("."),
						})),
					};
		}),
	};
}

/** Answers a stubbed route like the tests do (`[pattern, reply]`, searched in `METHOD /path`). */
function stubbedFetch(routes: readonly StubRoute[]) {
	return (input: RequestInfo | URL, init?: RequestInit) => {
		const request = new Request(input, init);
		const key = `${init?.method ?? request.method} ${new URL(request.url).pathname}`;
		const route = routes.find(([pattern]) =>
			new RegExp(pattern, "u").test(key)
		);
		const headers = { "x-request-id": "req_out" };
		if (route === undefined) {
			return Promise.resolve(
				Response.json({ error: `no stub for ${key}` }, { status: 599 })
			);
		}
		const [, reply] = route;
		if ("empty" in reply) {
			return Promise.resolve(new Response(null, { status: 204, headers }));
		}
		if ("text" in reply) {
			return Promise.resolve(new Response(reply.text, { headers }));
		}
		return Promise.resolve(Response.json(reply.json, { headers }));
	};
}

/** The `data` the TypeScript body answers for a case, as the adapters return it. */
async function expectedData(
	name: string,
	input: Record<string, unknown>,
	routes: readonly StubRoute[]
) {
	const tool = getRyuTool(name);
	if (tool === undefined) {
		throw new Error(`${name} is not registered`);
	}
	const ryu = new Ryu({ env: TOOL_OUTPUT_ENV, fetch: stubbedFetch(routes) });
	const result = toToolResultJson(await runRyuTool(ryu, tool, input));
	if (result.error !== null) {
		throw new Error(`${name} failed: ${result.error.message}`);
	}
	return result.data;
}

async function outputCases() {
	const cases: Record<string, unknown> = {};
	for (const [name, item] of Object.entries(TOOL_OUTPUT_CASES)) {
		cases[name] = {
			...item,
			expected: await expectedData(name, item.input, item.routes),
		};
	}
	const variants: unknown[] = [];
	for (const item of TOOL_OUTPUT_VARIANTS) {
		variants.push({
			...item,
			expected: await expectedData(item.tool, item.input, item.routes),
		});
	}
	return {
		description:
			"Stubbed replies for the outputSchema conformance tests, from packages/services/test/tool-output-cases.ts. Generated by bindings/python/tests/fixtures/services_tools.ts; do not edit. A route is [pattern, reply]: the first pattern found in `METHOD /path` answers with 200 JSON (json), 200 text (text) or 204 (empty). expected is the data the TypeScript body answers.",
		env: TOOL_OUTPUT_ENV,
		cases,
		variants,
	};
}

const MODES = {
	manifest,
	vectors,
	"output-cases": outputCases,
} as const;
const mode = process.argv[2] ?? "manifest";
if (!Object.hasOwn(MODES, mode)) {
	throw new Error(
		`Unknown mode ${mode}: pass manifest, vectors or output-cases.`
	);
}
